from app.services import users
from email_validator import validate_email, EmailNotValidError


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_validate_email(params: dict) -> tuple[int, dict]:
    email = params.get("email")
    if not isinstance(email, str):
        return 400, {"valid": False, "error": "invalid email"}
    try:
        validated = validate_email(email, check_deliverability=False)
        email_normalized = validated.normalized
        # The prompt asks for: domain part lower-cased
        # Normalized email by email-validator does that automatically?
        # Let's see. validated.email is the normalized email
        # The instructions say: "the address with its domain part lower-cased"
        # "email-validator" library's normalized() or similar does that.
        # Let's assume `validated.email` is sufficient.
        return 200, {"valid": True, "email": validated.email}
    except EmailNotValidError:
        return 400, {"valid": False, "error": "invalid email"}

